#!/usr/bin/env node
/**
 * Build stats.json for the GitHub Pages deep-dive pages: per-day commit and
 * churn activity for the whole repository history, aggregated from
 * `git log --numstat`.
 *
 * The site fetches this file at view time and overlays live GitHub API data
 * for the current day, so nothing about the repo's activity is hardcoded
 * into the pages. Regenerated by .github/workflows/site-stats.yml on every
 * push to main and once daily; local runs print the same file.
 *
 * Output shape:
 * {
 *   generated: '<UTC ISO>',
 *   days: [{ d: 'YYYY-MM-DD', c: number, a: number, del: number }]  // ascending
 * }
 *
 * Usage:
 *   node scripts/build-site-stats.cjs [--out stats.json | --stdout] [--selfcheck]
 *
 * --selfcheck recomputes the totals through an independent second pass
 * (`git log --shortstat`) and exits 1 when the two passes disagree — this is
 * the script's own test, run in CI before committing the file.
 */
'use strict'

const { execFileSync } = require('node:child_process')
const fs = require('node:fs')

function git(args, cwd) {
  return execFileSync('git', args, { cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
}

// Header marker for commit boundaries in log output. Chosen printable and
// date-anchored so a numstat row can never collide: rows start with digits
// or '-', never with '#'.
const HEADER = /^#commit# (\d{4}-\d{2}-\d{2})$/

/** Aggregate per-day { c, a, del } from `git log --numstat`. */
function collectDays(cwd) {
  // %as = author date, short ISO (YYYY-MM-DD), in the commit's recorded
  // timezone — deterministic on every machine, no TZ handling needed.
  const raw = git(['log', '--no-renames', '--format=#commit# %as', '--numstat'], cwd)
  const days = new Map()
  let rec = null
  for (const line of raw.split('\n')) {
    const h = line.match(HEADER)
    if (h) {
      if (!days.has(h[1])) days.set(h[1], { d: h[1], c: 0, a: 0, del: 0 })
      rec = days.get(h[1])
      rec.c += 1
      continue
    }
    if (rec === null) continue
    const m = line.match(/^(\d+|-)\t(\d+|-)\t/)
    if (!m) continue
    if (m[1] !== '-') rec.a += Number(m[1])
    if (m[2] !== '-') rec.del += Number(m[2])
  }
  return [...days.values()].sort((x, y) => (x.d < y.d ? -1 : 1))
}

/** Independent totals via `git log --shortstat` — the self-check second pass. */
function totalsViaShortstat(cwd) {
  const raw = git(['log', '--no-renames', '--format=#commit# %as', '--shortstat'], cwd)
  let commits = 0, a = 0, del = 0
  for (const line of raw.split('\n')) {
    if (HEADER.test(line)) { commits += 1; continue }
    const ins = line.match(/(\d+) insertion/)
    const dele = line.match(/(\d+) deletion/)
    if (ins) a += Number(ins[1])
    if (dele) del += Number(dele[1])
  }
  return { commits, additions: a, deletions: del }
}

function main() {
  const argv = process.argv.slice(2)
  const outIdx = argv.indexOf('--out')
  const out = outIdx >= 0 ? argv[outIdx + 1] : null
  const stdout = argv.includes('--stdout') || (!out && !argv.includes('--selfcheck'))
  const selfcheck = argv.includes('--selfcheck')

  const days = collectDays(process.cwd())
  const file = {
    generated: new Date().toISOString(),
    days,
  }
  if (selfcheck) {
    const viaNumstat = {
      commits: days.reduce((s, d) => s + d.c, 0),
      additions: days.reduce((s, d) => s + d.a, 0),
      deletions: days.reduce((s, d) => s + d.del, 0),
    }
    const viaShortstat = totalsViaShortstat(process.cwd())
    const ok = viaNumstat.commits === viaShortstat.commits
      && viaNumstat.additions === viaShortstat.additions
      && viaNumstat.deletions === viaShortstat.deletions
    process.stderr.write(
      `[site-stats selfcheck] numstat=${JSON.stringify(viaNumstat)} shortstat=${JSON.stringify(viaShortstat)} -> ${ok ? 'OK' : 'MISMATCH'}\n`,
    )
    if (!ok) process.exit(1)
  }
  const json = JSON.stringify(file) + '\n'
  if (out) fs.writeFileSync(out, json)
  if (stdout) process.stdout.write(json)
}

main()
